import com.squareup.moshi.JsonClass
import com.squareup.moshi.Moshi

// GreetingJsonAdapter is generated by moshi-kotlin-codegen
@JsonClass(generateAdapter = true)
data class Greeting(val name: String, val times: Int)

// internal: the tests see it, kotlinc and KSP get the module as a friend of them
@JsonClass(generateAdapter = true)
internal data class Signature(val by: String)

fun main() {
    val adapter = Moshi.Builder().build().adapter(Greeting::class.java)
    val json = adapter.toJson(Greeting("Moshi", 2))
    println(json)
    println(adapter.fromJson(json))
    println(adapter)
}
